"""Helpers for Step 1: append rows to RESULT, write LOG lines, remove a paper's rows."""
import csv, sys, subprocess, re

RES = 'data/inference_test/results/opus-5-5.csv'
LOG = 'data/inference_test/logs/opus-5-5_log.csv'
COLS = ["Genus","Species","subsp","scientific_name","native_status","Family","fire_response categorical_surv1","resprouter_type","PJP mths","primary_juvenile_period","Age at first flower production from seed_repr3","secondary_juvenile_period","Time to first flower production resprout_repr3a","Time to 50% flowering_repr4","Time to 50% flowering","Time to 80% flowering","Recovery_time","Time_unit","Location_name","Latitude","Longitude","Rainfall_mm","Fire_type","Fire_season_categorical","Fire_severity_categorical","Notes","Source","File_name"]
SHORT = {"surv1": "fire_response categorical_surv1", "rtype": "resprouter_type", "pjp": "PJP mths",
         "pjpy": "primary_juvenile_period", "repr3": "Age at first flower production from seed_repr3",
         "sjp": "secondary_juvenile_period", "repr3a": "Time to first flower production resprout_repr3a",
         "repr4": "Time to 50% flowering_repr4", "t50": "Time to 50% flowering", "t80": "Time to 80% flowering",
         "rec": "Recovery_time", "unit": "Time_unit", "loc": "Location_name", "lat": "Latitude", "lon": "Longitude",
         "rain": "Rainfall_mm", "ftype": "Fire_type", "season": "Fire_season_categorical",
         "sev": "Fire_severity_categorical", "native": "native_status"}


def clean(v):
    v = '' if v is None else str(v)
    v = v.replace('–', '-').replace('—', '-').replace('‐', '-').replace('‑', '-')
    return re.sub(r'\s+', ' ', v).strip()


def row(**kw):
    d = {c: '' for c in COLS}
    for k, v in kw.items():
        d[SHORT.get(k, k)] = clean(v)
    if d['Genus'] and d['Species'] and d['Genus'] != 'NA':
        d['scientific_name'] = d['Genus'] + ' ' + d['Species']
    return d


def append(rows):
    with open(RES, 'a', newline='', encoding='utf-8') as f:
        w = csv.DictWriter(f, COLS, lineterminator='\n')
        for r in rows:
            assert set(r) == set(COLS)
            w.writerow(r)
    return len(rows)


def na_row(stem, reason, source=None):
    d = {c: 'NA' for c in COLS}
    d['Notes'] = clean(reason); d['Source'] = clean(source or stem); d['File_name'] = stem
    return d


def remove(stem):
    rows = list(csv.reader(open(RES, encoding='utf-8')))
    keep = [r for r in rows if r[-1] != stem]
    with open(RES, 'w', newline='', encoding='utf-8') as f:
        csv.writer(f, lineterminator='\n').writerows(keep)
    return len(rows) - len(keep)


def count(stem):
    return sum(1 for r in csv.reader(open(RES, encoding='utf-8')) if r[-1] == stem)


def log(paper, status, n, started, finished, note):
    with open(LOG, 'a', newline='', encoding='utf-8') as f:
        csv.writer(f, lineterminator='\n').writerow([paper, status, n, started, finished, clean(note)] + [''] * 6)


def now():
    return subprocess.check_output(['date', '-u', '+%FT%TZ']).decode().strip()

